SET NAMES utf8mb4;
SET time_zone = '+00:00';

CREATE TABLE auth_users (id char(36) PRIMARY KEY DEFAULT (UUID()),email varchar(320) NOT NULL,password_hash varchar(255) NOT NULL,display_name varchar(150) NOT NULL,active boolean NOT NULL DEFAULT true,created_at timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),UNIQUE KEY users_email_unique(email)) ENGINE=InnoDB;
CREATE TABLE auth_roles (id char(36) PRIMARY KEY DEFAULT (UUID()),code varchar(80) NOT NULL UNIQUE,name varchar(120) NOT NULL,created_at timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6)) ENGINE=InnoDB;
CREATE TABLE auth_permissions (id char(36) PRIMARY KEY DEFAULT (UUID()),code varchar(120) NOT NULL UNIQUE,description text NOT NULL) ENGINE=InnoDB;
CREATE TABLE auth_user_roles (user_id char(36) NOT NULL,role_id char(36) NOT NULL,PRIMARY KEY(user_id,role_id),FOREIGN KEY(user_id) REFERENCES auth_users(id) ON DELETE CASCADE,FOREIGN KEY(role_id) REFERENCES auth_roles(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE auth_role_permissions (role_id char(36) NOT NULL,permission_id char(36) NOT NULL,PRIMARY KEY(role_id,permission_id),FOREIGN KEY(role_id) REFERENCES auth_roles(id) ON DELETE CASCADE,FOREIGN KEY(permission_id) REFERENCES auth_permissions(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE auth_sessions (id char(36) PRIMARY KEY DEFAULT (UUID()),token_hash binary(32) NOT NULL UNIQUE,user_id char(36) NOT NULL,csrf_token varchar(64) NOT NULL,expires_at datetime(6) NOT NULL,last_seen_at timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),ip varchar(45),user_agent text,created_at timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),KEY sessions_user_idx(user_id),KEY sessions_expiry_idx(expires_at),FOREIGN KEY(user_id) REFERENCES auth_users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE auth_login_logs (id bigint unsigned AUTO_INCREMENT PRIMARY KEY,email varchar(320) NOT NULL,user_id char(36),success boolean NOT NULL,ip varchar(45),created_at timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),KEY login_time_idx(created_at),FOREIGN KEY(user_id) REFERENCES auth_users(id) ON DELETE SET NULL) ENGINE=InnoDB;

CREATE TABLE org_organizations (id char(36) PRIMARY KEY DEFAULT (UUID()),slug varchar(100) NOT NULL UNIQUE,name varchar(180) NOT NULL,active boolean NOT NULL DEFAULT true,created_at timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6)) ENGINE=InnoDB;
CREATE TABLE org_units (id char(36) PRIMARY KEY DEFAULT (UUID()),organization_id char(36) NOT NULL,parent_id char(36),name varchar(180) NOT NULL,UNIQUE KEY unit_org_id(organization_id,id),FOREIGN KEY(organization_id) REFERENCES org_organizations(id) ON DELETE CASCADE,FOREIGN KEY(parent_id) REFERENCES org_units(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE org_memberships (organization_id char(36) NOT NULL,user_id char(36) NOT NULL,status enum('active','suspended') NOT NULL DEFAULT 'active',created_at timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),PRIMARY KEY(organization_id,user_id),FOREIGN KEY(organization_id) REFERENCES org_organizations(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES auth_users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE org_groups (id char(36) PRIMARY KEY DEFAULT (UUID()),organization_id char(36) NOT NULL,name varchar(180) NOT NULL,UNIQUE KEY group_org_name(organization_id,name),FOREIGN KEY(organization_id) REFERENCES org_organizations(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE org_group_members (group_id char(36) NOT NULL,user_id char(36) NOT NULL,PRIMARY KEY(group_id,user_id),FOREIGN KEY(group_id) REFERENCES org_groups(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES auth_users(id) ON DELETE CASCADE) ENGINE=InnoDB;

CREATE TABLE drive_drives (id char(36) PRIMARY KEY DEFAULT (UUID()),organization_id char(36),owner_user_id char(36),name varchar(180) NOT NULL,type enum('personal','shared','public') NOT NULL,personal_owner_key char(36) GENERATED ALWAYS AS (IF(type='personal',owner_user_id,NULL)) STORED,public_org_key char(36) GENERATED ALWAYS AS (IF(type='public',organization_id,NULL)) STORED,created_at timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),UNIQUE KEY one_personal_drive(personal_owner_key),UNIQUE KEY one_public_drive(public_org_key),FOREIGN KEY(organization_id) REFERENCES org_organizations(id) ON DELETE CASCADE,FOREIGN KEY(owner_user_id) REFERENCES auth_users(id) ON DELETE CASCADE,CHECK((type='personal' AND owner_user_id IS NOT NULL) OR (type<>'personal' AND organization_id IS NOT NULL))) ENGINE=InnoDB;
CREATE TABLE drive_drive_members (drive_id char(36) NOT NULL,user_id char(36) NOT NULL,role enum('viewer','commenter','editor','manager','owner') NOT NULL,PRIMARY KEY(drive_id,user_id),FOREIGN KEY(drive_id) REFERENCES drive_drives(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES auth_users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE storage_objects (id char(36) PRIMARY KEY DEFAULT (UUID()),storage_key varchar(255) NOT NULL UNIQUE,size_bytes bigint unsigned NOT NULL,checksum_sha256 char(64) NOT NULL,state enum('temporary','ready','quarantined') NOT NULL,created_at timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6)) ENGINE=InnoDB;
CREATE TABLE drive_nodes (id char(36) PRIMARY KEY DEFAULT (UUID()),drive_id char(36) NOT NULL,parent_id char(36),name varchar(255) NOT NULL,type enum('file','folder') NOT NULL,mime_type varchar(255),size_bytes bigint unsigned NOT NULL DEFAULT 0,storage_object_id char(36),status enum('uploading','ready','quarantined','failed') NOT NULL DEFAULT 'ready',created_by char(36) NOT NULL,updated_by char(36) NOT NULL,deleted_at datetime(6),created_at timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),active_parent_key char(36) GENERATED ALWAYS AS (IF(deleted_at IS NULL,COALESCE(parent_id,'00000000-0000-0000-0000-000000000000'),NULL)) STORED,active_name_key varchar(255) GENERATED ALWAYS AS (IF(deleted_at IS NULL,LOWER(name),NULL)) STORED,UNIQUE KEY nodes_active_name_unique(drive_id,active_parent_key,active_name_key),UNIQUE KEY nodes_drive_id(drive_id,id),KEY nodes_browse_idx(drive_id,parent_id,deleted_at),FULLTEXT KEY nodes_search_idx(name),FOREIGN KEY(drive_id) REFERENCES drive_drives(id) ON DELETE CASCADE,FOREIGN KEY(parent_id) REFERENCES drive_nodes(id),FOREIGN KEY(storage_object_id) REFERENCES storage_objects(id),FOREIGN KEY(created_by) REFERENCES auth_users(id),FOREIGN KEY(updated_by) REFERENCES auth_users(id),CHECK(name<>'' AND name NOT IN ('.','..') AND name NOT LIKE '%/%' AND name NOT LIKE '%\\%'),CHECK(parent_id IS NULL OR parent_id<>id)) ENGINE=InnoDB;
CREATE TABLE drive_file_versions (id char(36) PRIMARY KEY DEFAULT (UUID()),node_id char(36) NOT NULL,version_no int unsigned NOT NULL,object_id char(36),size_bytes bigint unsigned NOT NULL,checksum_sha256 char(64) NOT NULL,created_by char(36) NOT NULL,created_at timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),UNIQUE KEY version_unique(node_id,version_no),FOREIGN KEY(node_id) REFERENCES drive_nodes(id) ON DELETE CASCADE,FOREIGN KEY(object_id) REFERENCES storage_objects(id),FOREIGN KEY(created_by) REFERENCES auth_users(id)) ENGINE=InnoDB;
CREATE TABLE drive_favorites (user_id char(36) NOT NULL,node_id char(36) NOT NULL,created_at timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),PRIMARY KEY(user_id,node_id),FOREIGN KEY(user_id) REFERENCES auth_users(id) ON DELETE CASCADE,FOREIGN KEY(node_id) REFERENCES drive_nodes(id) ON DELETE CASCADE) ENGINE=InnoDB;

CREATE TABLE storage_upload_sessions (id char(36) PRIMARY KEY DEFAULT (UUID()),drive_id char(36) NOT NULL,user_id char(36) NOT NULL,filename varchar(255) NOT NULL,expected_size bigint unsigned,status varchar(20) NOT NULL DEFAULT 'pending',expires_at datetime(6) NOT NULL,created_at timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),FOREIGN KEY(drive_id) REFERENCES drive_drives(id),FOREIGN KEY(user_id) REFERENCES auth_users(id)) ENGINE=InnoDB;
CREATE TABLE storage_upload_parts (upload_id char(36) NOT NULL,part_no int unsigned NOT NULL,storage_key varchar(255) NOT NULL,size_bytes bigint unsigned NOT NULL,checksum_sha256 char(64) NOT NULL,PRIMARY KEY(upload_id,part_no),FOREIGN KEY(upload_id) REFERENCES storage_upload_sessions(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE storage_quotas (drive_id char(36) PRIMARY KEY,max_bytes bigint unsigned NOT NULL,FOREIGN KEY(drive_id) REFERENCES drive_drives(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE sharing_resource_permissions (id char(36) PRIMARY KEY DEFAULT (UUID()),node_id char(36) NOT NULL,subject_type enum('user','group') NOT NULL,subject_id char(36) NOT NULL,role enum('viewer','commenter','editor','manager','owner') NOT NULL,created_at timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),FOREIGN KEY(node_id) REFERENCES drive_nodes(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE sharing_share_links (id char(36) PRIMARY KEY DEFAULT (UUID()),node_id char(36) NOT NULL,token_hash binary(32) NOT NULL UNIQUE,expires_at datetime(6),created_by char(36) NOT NULL,created_at timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),FOREIGN KEY(node_id) REFERENCES drive_nodes(id) ON DELETE CASCADE,FOREIGN KEY(created_by) REFERENCES auth_users(id)) ENGINE=InnoDB;
CREATE TABLE audit_activity_logs (id bigint unsigned AUTO_INCREMENT PRIMARY KEY,organization_id char(36),actor_user_id char(36),action varchar(100) NOT NULL,node_id char(36),metadata json NOT NULL,ip varchar(45),created_at timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),KEY activity_org_time_idx(organization_id,created_at),FOREIGN KEY(organization_id) REFERENCES org_organizations(id),FOREIGN KEY(actor_user_id) REFERENCES auth_users(id),FOREIGN KEY(node_id) REFERENCES drive_nodes(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE audit_download_logs (id bigint unsigned AUTO_INCREMENT PRIMARY KEY,organization_id char(36),node_id char(36) NOT NULL,user_id char(36),ip varchar(45),created_at timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),FOREIGN KEY(organization_id) REFERENCES org_organizations(id),FOREIGN KEY(node_id) REFERENCES drive_nodes(id),FOREIGN KEY(user_id) REFERENCES auth_users(id)) ENGINE=InnoDB;
CREATE TABLE system_settings (`key` varchar(120) PRIMARY KEY,value json NOT NULL,updated_at timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6)) ENGINE=InnoDB;
CREATE TABLE system_jobs (id char(36) PRIMARY KEY DEFAULT (UUID()),type varchar(100) NOT NULL,payload json NOT NULL,status varchar(20) NOT NULL DEFAULT 'pending',created_at timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6)) ENGINE=InnoDB;
CREATE TABLE system_notifications (id char(36) PRIMARY KEY DEFAULT (UUID()),user_id char(36) NOT NULL,title text NOT NULL,read_at datetime(6),created_at timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),FOREIGN KEY(user_id) REFERENCES auth_users(id) ON DELETE CASCADE) ENGINE=InnoDB;

DELIMITER $$
CREATE TRIGGER drive_nodes_validate_insert BEFORE INSERT ON drive_nodes FOR EACH ROW BEGIN DECLARE parent_drive char(36); IF NEW.parent_id IS NOT NULL THEN SELECT drive_id INTO parent_drive FROM drive_nodes WHERE id=NEW.parent_id AND type='folder' AND deleted_at IS NULL; IF parent_drive IS NULL OR parent_drive<>NEW.drive_id THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='parent must be active folder in same drive'; END IF; END IF; END$$
CREATE TRIGGER drive_nodes_validate_update BEFORE UPDATE ON drive_nodes FOR EACH ROW BEGIN DECLARE ancestor char(36); DECLARE parent_drive char(36); IF NEW.parent_id IS NOT NULL THEN SELECT drive_id INTO parent_drive FROM drive_nodes WHERE id=NEW.parent_id AND type='folder' AND deleted_at IS NULL; IF parent_drive IS NULL OR parent_drive<>NEW.drive_id THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='parent must be active folder in same drive'; END IF; SET ancestor=NEW.parent_id; WHILE ancestor IS NOT NULL DO IF ancestor=NEW.id THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='folder cycle detected'; END IF; SET ancestor=(SELECT parent_id FROM drive_nodes WHERE id=ancestor LIMIT 1); END WHILE; END IF; END$$
CREATE PROCEDURE bootstrap_superadmin(IN p_email varchar(320),IN p_hash varchar(255),IN p_name varchar(150),OUT p_user_id char(36)) BEGIN SELECT id INTO p_user_id FROM auth_users WHERE email=LOWER(p_email) LIMIT 1; IF p_user_id IS NULL THEN SET p_user_id=UUID(); INSERT INTO auth_users(id,email,password_hash,display_name) VALUES(p_user_id,LOWER(p_email),p_hash,p_name); ELSE UPDATE auth_users SET password_hash=p_hash,display_name=p_name,active=1 WHERE id=p_user_id; END IF; INSERT IGNORE INTO auth_user_roles(user_id,role_id) SELECT p_user_id,id FROM auth_roles WHERE code='super_admin'; INSERT IGNORE INTO drive_drives(id,owner_user_id,name,type) VALUES(UUID(),p_user_id,'Drive Saya','personal'); END$$
DELIMITER ;

INSERT INTO auth_roles(id,code,name) VALUES(UUID(),'super_admin','Super Administrator'),(UUID(),'org_admin','Organization Administrator'),(UUID(),'member','Member');
INSERT INTO auth_permissions(id,code,description) VALUES(UUID(),'admin.manage','Manage system'),(UUID(),'users.manage','Manage users'),(UUID(),'drives.manage','Manage drives'),(UUID(),'public_drive.write','Modify public drive'),(UUID(),'files.read','Read files'),(UUID(),'files.write','Modify files');
INSERT INTO auth_role_permissions(role_id,permission_id) SELECT r.id,p.id FROM auth_roles r CROSS JOIN auth_permissions p WHERE r.code='super_admin';
INSERT INTO auth_role_permissions(role_id,permission_id) SELECT r.id,p.id FROM auth_roles r JOIN auth_permissions p ON p.code IN ('files.read','files.write') WHERE r.code='member';
